                                placeholder="e.g., users, posts, products"
                                value={collectionName()}
                                onInput={(e) => setCollectionName(e.currentTarget.value)}
                                required
                                autocomplete="off"
                            />
                            <div class={helpText}>
                                Use lowercase letters, numbers, and underscores only
                            </div>
                        </div>

                        <div class={formGroup}>
                            <label class={label} for="description">
                                Description
                            </label>
                            <textarea
                                id="description"
                                class={textarea}
                                placeholder="Optional description for this collection..."
                                value={description()}
                                onInput={(e) => setDescription(e.currentTarget.value)}
                            />
                        </div>

                        <div class={fieldsSection}>
                            <div class={fieldsSectionHeader}>
                                <label class={label}>Fields</label>
                                <button type="button" class={addFieldButton} onClick={addField}>
                                    <span>+</span>
                                    <span>Add Field</span>
                                </button>
                            </div>
                            {fields().length === 0 ? (
                                <div class={emptyFieldsMessage}>
                                    No fields defined. Click "Add Field" to add database columns.
                                </div>
                            ) : (
                                <For each={fields()}>
                                    {(field, index) => (
                                        <div class={fieldRow}>
                                            <input
                                                type="text"
                                                class={fieldInput}
                                                placeholder="Field name"
                                                value={field.name}
                                                onInput={(e) => updateField(index(), "name", e.currentTarget.value)}
                                                autocomplete="off"
                                            />
                                            <select
                                                class={fieldSelect}
                                                value={field.type}
                                                onChange={(e) => updateField(index(), "type", e.currentTarget.value)}
                                            >
                                                <For each={FIELD_TYPES}>
                                                    {(type) => <option value={type}>{type}</option>}
                                                </For>
                                            </select>
                                            <button
                                                type="button"
                                                class={removeFieldButton}
                                                onClick={() => removeField(index())}
                                                title="Remove field"
                                            >
                                                ✕
                                            </button>
                                        </div>
                                    )}
                                </For>
                            )}
                            <div class={helpText}>
                                Define the columns for this collection's database table
                            </div>
                        </div>
                    </div>

                    <div class={modalFooter}>
                        <button
                            type="button"
                            class={cancelButton}
                            onClick={handleClose}
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            class={submitButton}
                            disabled={!collectionName().trim()}
                        >
                            Create Collection
                        </button>
                    </div>
                </form>
            </div>
        </>
    );
};
